begin;
do $test$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();outside_id uuid:=gen_random_uuid();
 sport uuid;tid uuid;mid uuid;pool_id uuid:=gen_random_uuid();snapshot jsonb;live_rows jsonb;source jsonb;source_id uuid;queue jsonb;source_match uuid;
 day text:=(now() at time zone 'Europe/Amsterdam')::date::text;
begin
 insert into auth.users(id,email,email_confirmed_at,aud,role) values(a,a||'@qa.invalid',now(),'authenticated','authenticated'),(u,u||'@qa.invalid',now(),'authenticated','authenticated'),(other_id,other_id||'@qa.invalid',now(),'authenticated','authenticated'),(outside_id,outside_id||'@qa.invalid',now(),'authenticated','authenticated');
 insert into public.profiles(id,username,display_name) values(a,'qa-admin-'||a,'Admin'),(u,'qa-player-'||u,'Frozen name'),(other_id,'qa-other-'||other_id,'Other'),(outside_id,'qa-outside-'||outside_id,'Outsider');
 insert into public.user_roles values(a,'admin'),(u,'user'),(other_id,'user'),(outside_id,'user');
 select id into sport from public.sports where slug='darts';
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);
 tid:=public.create_knockout_game('QA final snapshot',sport,'players',array['QA A','QA B'],now()+interval '1 day','[{"unit":"legs","first_to":6,"winner_points":1,"exact_points":3}]','replacement',now()+interval '2 days','draft');
 mid:=(public.get_knockout_schema(tid)->'matches'->0->>'id')::uuid;perform public.edit_knockout(tid,'schedule',mid,jsonb_build_object('start',now()+interval '1 day','unit','legs','first_to',6));perform public.edit_knockout(tid,'publish');
 perform set_config('role','none',true);select id into mid from public.matches where tournament_id=tid;
 perform set_config('role','authenticated',true);perform set_config('request.jwt.claim.sub',u::text,true);perform public.join_tournament(tid);perform public.submit_match_prediction(mid,6,3);
 perform set_config('request.jwt.claim.sub',other_id::text,true);perform public.join_tournament(tid);perform public.submit_match_prediction(mid,6,4);
 perform set_config('role','none',true);
 insert into public.pools(id,tournament_id,name,owner_id) values(pool_id,tid,'Frozen pool',u);insert into public.pool_members(pool_id,user_id) values(pool_id,u);
 update public.matches set predictions_enabled=false,scheduled_start=now()-interval '4 days' where id=mid;
 update public.tournaments set starts_at=now()-interval '5 days',ends_at=now()-interval '71 hours' where id=tid;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);perform public.admin_record_match_result(mid,6,3);perform set_config('role','none',true);
 if predict_private.freeze_tournament(tid) then raise exception 'FAIL before 72 hours';end if;
 update public.tournaments set ends_at=now()-interval '73 hours' where id=tid;
 perform set_config('role','authenticated',true);select jsonb_agg(to_jsonb(r) order by rank_position,display_name,user_id) into live_rows from public.get_tournament_leaderboard(tid)r;perform set_config('role','none',true);
 if not predict_private.freeze_tournament(tid) then raise exception 'FAIL freeze eligible';end if;
 if predict_private.freeze_tournament(tid) then raise exception 'FAIL archive not idempotent';end if;
 if not exists(select 1 from public.matches where id=mid) or (select count(*) from public.match_predictions where match_id=mid)<>2 then raise exception 'FAIL original data deleted';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('role','authenticated',true);snapshot:=public.get_tournament_archive(tid);
 if snapshot->'standings'<>live_rows or jsonb_array_length(snapshot->'pools')<>1 then raise exception 'FAIL standings differ % %',snapshot->'standings',live_rows;end if;
 if not exists(select 1 from jsonb_array_elements(public.get_tournament_archive_catalog()) x where x->>'id'=tid::text) then raise exception 'FAIL archive list';end if;
 if exists(select 1 from jsonb_array_elements(public.get_active_tournament_catalog()->'tournaments') x where x->>'id'=tid::text) then raise exception 'FAIL archived on active home';end if;
 perform set_config('request.jwt.claim.sub',other_id::text,true);
 if jsonb_array_length(public.get_tournament_archive(tid)->'pools')<>0 then raise exception 'FAIL pool privacy';end if;
 begin perform public.get_tournament_leaderboard(tid,pool_id);raise exception 'FAIL unauthorized pool standings';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outside_id::text,true);
 begin perform public.get_tournament_archive(tid);raise exception 'FAIL outsider archive';exception when insufficient_privilege then null;end;
 perform set_config('role','none',true);update public.profiles set display_name='Changed later' where id=u;
 perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('role','authenticated',true);
 if public.get_tournament_archive(tid)->'standings'<>snapshot->'standings' then raise exception 'FAIL names recalculated';end if;
 if (select display_name from public.get_tournament_leaderboard(tid) where user_id=u)<>'Frozen name' then raise exception 'FAIL legacy leaderboard recalculated';end if;
 perform set_config('role','none',true);
 begin update public.matches set home_score=3,away_score=6 where id=mid;raise exception 'FAIL archived match mutable';exception when insufficient_privilege then null;end;
 source:=jsonb_build_object('url','https://mastercaller.com/tournaments/european-championship/2026/results','title','QA pending source','start_date',day,'end_date',day,'roster','["QA C","QA D","QA E","QA F"]'::jsonb,
 'rounds','[{"order":1,"name":"Semi-finals","unit":"legs","first_to":6},{"order":2,"name":"Final","unit":"legs","first_to":6}]'::jsonb,
 'bracket',jsonb_build_array(jsonb_build_object('order',1,'position',1,'home_name','QA C','away_name','QA D','start',now()-interval '1 hour','date',day),jsonb_build_object('order',1,'position',2,'home_name','QA E','away_name','QA F','start',now()+interval '1 hour','date',day),jsonb_build_object('order',2,'position',1,'home_name','','away_name','','start',null,'date',null)),'records','[]'::jsonb);
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);source_id:=public.create_mastercaller_game(source,'QA pending source',1,3,'replacement');
 queue:=public.admin_match_overview(source_id,true);
 if jsonb_array_length(queue)<>1 then raise exception 'FAIL future or unknown in queue %',queue;end if;
 source_match:=(queue->0->>'match_id')::uuid;
 begin perform public.manage_tournament(source_id,'metadata',jsonb_build_object('name','QA pending source','start',now()+interval '1 day','end',now()+interval '2 days'));raise exception 'FAIL source period editable';exception when insufficient_privilege then null;end;
 perform public.admin_record_source_result(source_match,6,3);
 if jsonb_array_length(public.admin_match_overview(source_id,true))<>0 then raise exception 'FAIL completed result remains in queue';end if;
 perform set_config('role','none',true);perform predict_private.mc_enter(source_id);update public.tournaments set starts_at=now()-interval '5 days',ends_at=now()-interval '4 days' where id=source_id;perform predict_private.mc_exit(source_id);
 if predict_private.freeze_tournament(source_id) then raise exception 'FAIL incomplete tournament frozen';end if;
 perform set_config('role','authenticated',true);
 if not public.admin_result_alert()->'blocked_archives' @> jsonb_build_array(jsonb_build_object('id',source_id)) then raise exception 'FAIL missing archive warning';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform public.admin_result_alert();raise exception 'FAIL player alert';exception when insufficient_privilege then null;end;
 begin perform 1 from predict_private.tournament_final_snapshots;raise exception 'FAIL raw snapshot access';exception when insufficient_privilege then null;end;
 perform set_config('role','anon',true);
 begin perform public.get_tournament_archive(tid);raise exception 'FAIL anonymous archive';exception when insufficient_privilege then null;end;
end $test$;
rollback;
